mapper.select:
/* CastRestTestMapper.retrieveFlightSchedule(CastReqGetResourceDto dto) */ SELECT LISTAGG(NVL(X.domStatus, ' '),',') WITHIN GROUP (ORDER BY X.DomStatus, X.FlightDirection, X.DepArrTerminal, X.FlightNumber) AS domStatus , LISTAGG(NVL(X.flightDirection, ' '),',') WITHIN GROUP (ORDER BY X.DomStatus, X.FlightDirection, X.DepArrTerminal, X.FlightNumber) AS flightDirection , LISTAGG(NVL(X.depArrTerminal, ' '),',') WITHIN GROUP (ORDER BY X.DomStatus, X.FlightDirection, X.DepArrTerminal, X.FlightNumber) AS depArrTerminal , LISTAGG(NVL(X.airlineCode, ' '),',') WITHIN GROUP (ORDER BY X.DomStatus, X.FlightDirection, X.DepArrTerminal, X.FlightNumber) AS airlineCode , LISTAGG(NVL(X.operatorCat, ' '),',') WITHIN GROUP (ORDER BY X.DomStatus, X.FlightDirection, X.DepArrTerminal, X.FlightNumber) AS operatorCat , LISTAGG(NVL(X.flightNumber, ' '),',') WITHIN GROUP (ORDER BY X.DomStatus, X.FlightDirection, X.DepArrTerminal, X.FlightNumber) AS flightNumber , LISTAGG(NVL(X.flightNumberID, ' '),',') WITHIN GROUP (ORDER BY X.DomStatus, X.FlightDirection, X.DepArrTerminal, X.FlightNumber) AS flightNumberID , LISTAGG(NVL(X.scheduleTime, ' '),',') WITHIN GROUP (ORDER BY X.DomStatus, X.FlightDirection, X.DepArrTerminal, X.FlightNumber) AS scheduleTime , LISTAGG(NVL(X.estimatedTime, ' '),',') WITHIN GROUP (ORDER BY X.DomStatus, X.FlightDirection, X.DepArrTerminal, X.FlightNumber) AS estimatedTime , LISTAGG(NVL(X.actualTime, ' '),',') WITHIN GROUP (ORDER BY X.DomStatus, X.FlightDirection, X.DepArrTerminal, X.FlightNumber) AS actualTime , LISTAGG(NVL(X.airportCode, ' '),',') WITHIN GROUP (ORDER BY X.DomStatus, X.FlightDirection, X.DepArrTerminal, X.FlightNumber) AS airportCode , LISTAGG(NVL(TO_CHAR(X.standNumber), ' '),',') WITHIN GROUP (ORDER BY X.DomStatus, X.FlightDirection, X.DepArrTerminal, X.FlightNumber) AS standNumber , LISTAGG(NVL(TO_CHAR(X.gate), ' '),',') WITHIN GROUP (ORDER BY X.DomStatus, X.FlightDirection, X.DepArrTerminal, X.FlightNumber) AS gate , LISTAGG(NVL(X.contactRemote, ' '),',') WITHIN GROUP (ORDER BY X.DomStatus, X.FlightDirection, X.DepArrTerminal, X.FlightNumber) AS contactRemote , LISTAGG(NVL(TO_CHAR(X.seats), ' '),',') WITHIN GROUP (ORDER BY X.DomStatus, X.FlightDirection, X.DepArrTerminal, X.FlightNumber) AS seats , LISTAGG(NVL(TO_CHAR(X.paxCount), ' '),',') WITHIN GROUP (ORDER BY X.DomStatus, X.FlightDirection, X.DepArrTerminal, X.FlightNumber) AS paxCount , LISTAGG(NVL(TO_CHAR(X.transferPax), ' '),',') WITHIN GROUP (ORDER BY X.DomStatus, X.FlightDirection, X.DepArrTerminal, X.FlightNumber) AS transferPax , LISTAGG(NVL(X.belt, ' '),',') WITHIN GROUP (ORDER BY X.DomStatus, X.FlightDirection, X.DepArrTerminal, X.FlightNumber) AS belt , LISTAGG(NVL(X.flightType, ' '),',') WITHIN GROUP (ORDER BY X.DomStatus, X.FlightDirection, X.DepArrTerminal, X.FlightNumber) AS flightType , LISTAGG(NVL(X.checkInRange, ' '),',') WITHIN GROUP (ORDER BY X.DomStatus, X.FlightDirection, X.DepArrTerminal, X.FlightNumber) AS checkInRange , LISTAGG(NVL(X.aircraftType, ' '),',') WITHIN GROUP (ORDER BY X.DomStatus, X.FlightDirection, X.DepArrTerminal, X.FlightNumber) AS aircraftType , LISTAGG(NVL(X.sbdAvailable, ' '),',') WITHIN GROUP (ORDER BY X.DomStatus, X.FlightDirection, X.DepArrTerminal, X.FlightNumber) AS sbdAvailable , LISTAGG(NVL(X.triangle, ' '),',') WITHIN GROUP (ORDER BY X.DomStatus, X.FlightDirection, X.DepArrTerminal, X.FlightNumber) AS triangle , LISTAGG(NVL(X.bus, ' '),',') WITHIN GROUP (ORDER BY X.DomStatus, X.FlightDirection, X.DepArrTerminal, X.FlightNumber) AS bus , LISTAGG(NVL(X.arrivalGate, ' '),',') WITHIN GROUP (ORDER BY X.DomStatus, X.FlightDirection, X.DepArrTerminal, X.FlightNumber) AS arrivalGate , LISTAGG(NVL(X.baggageT1, ' '),',') WITHIN GROUP (ORDER BY X.DomStatus, X.FlightDirection, X.DepArrTerminal, X.FlightNumber) AS baggageT1 , LISTAGG(NVL(X.baggageT2, ' '),',') WITHIN GROUP (ORDER BY X.DomStatus, X.FlightDirection, X.DepArrTerminal, X.FlightNumber) AS baggageT2 , REPLACE(TO_CHAR(SYSDATE,'yyyy-mm-dd hh24:mi:ss'),' ','T') AS lastModified FROM (
WITH /* 2) 기준 운항 집합 */ BASE_GD AS ( SELECT 'FS001' AS RESOURCE_ID, CASE WHEN A.DOM_INT_SE_CD = 'I' THEN 'Int' WHEN A.DOM_INT_SE_CD = 'D' AND A.TRDOMFLT_YN = 'Y' THEN 'Int' WHEN A.DOM_INT_SE_CD = 'D' AND (A.TRDOMFLT_YN <> 'Y' OR A.TRDOMFLT_YN IS NULL) THEN 'Dom' ELSE '' END AS DOM_INT_SE_CD, A.ARR_DEP_SE_CD, A.TER_ID AS CF_TER_ID_X, A.ALN_CD, A.GD_SE_DT AS SCHD_DT, A.SCHD_HM, A.FLT_NM, A.CLOSING_FLT_NM, A.FLT_ID, A.FLT_NM || '_' || SUBSTR(A.GD_SE_DT, 1, 4) || '-' || SUBSTR(A.GD_SE_DT, 5, 2) || '-' || SUBSTR(A.GD_SE_DT, 7, 2) || 'T' || SUBSTR(A.SCHD_HM, 1, 2) || ':' || SUBSTR(A.SCHD_HM, 3, 2) || ':00.000' AS FLT_NM_ID, SUBSTR(A.GD_SE_DT, 1, 4) || '-' || SUBSTR(A.GD_SE_DT, 5, 2) || '-' || SUBSTR(A.GD_SE_DT, 7, 2) || 'T' || SUBSTR(A.SCHD_HM, 1, 2) || ':' || SUBSTR(A.SCHD_HM, 3, 2) || ':00.000' AS SCHD_TIME, CASE WHEN TRIM(A.ESTM_HM) IS NOT NULL THEN SUBSTR(A.GD_SE_DT, 1, 4) || '-' || SUBSTR(A.GD_SE_DT, 5, 2) || '-' || SUBSTR(A.GD_SE_DT, 7, 2) || 'T' || SUBSTR(A.ESTM_HM, 1, 2) || ':' || SUBSTR(A.ESTM_HM, 3, 2) || ':00.000' ELSE '' END AS ESTM_TIME, CASE WHEN TRIM(A.ACTL_HM) IS NOT NULL THEN SUBSTR(A.GD_SE_DT, 1, 4) || '-' || SUBSTR(A.GD_SE_DT, 5, 2) || '-' || SUBSTR(A.GD_SE_DT, 7, 2) || 'T' || SUBSTR(A.ACTL_HM, 1, 2) || ':' || SUBSTR(A.ACTL_HM, 3, 2) || ':00.000' ELSE '' END AS ACTL_TIME, A.APT_CD AS ARR_DEP_APT_CD, NULLIF(TRIM(A.STND_NO), '') AS STND_NO_RAW, NULLIF(TRIM(A.GATE_NO), '') AS GATE_NO_RAW, A.AC_SEAT_CNT, A.INPUT_YN, A.TOT_CRG_PAX_CNT, A.TOT_FREE_PAX_CNT, A.RSRV_PAX_CNT, A.TOT_TRPAX_CNT, A.RSRV_TRPAX_CNT, CASE WHEN A.INPUT_YN = 'Y' THEN A.TOT_TRPAX_CNT WHEN A.INPUT_YN = 'N' THEN A.RSRV_TRPAX_CNT ELSE 0 END AS TR_PAX_CNT, CASE WHEN TRIM(A.CRS_NO) = '0' THEN NULL ELSE NULLIF(TRIM(A.CRS_NO), '') END AS CRS_NO_RAW, A.AC_DTL_TY_CD AS AC_TYPE, CASE WHEN A.GD_IRR_YN IN ('0', 'N') THEN 'Schedule' WHEN A.GD_IRR_YN IN ('1', 'Y') THEN 'Charter' ELSE '' END AS IRR_FLT_YN, A.TRDOMFLT_YN FROM PMOWN.DROP_AA_TN_AS_GD_DATA A WHERE 1 = 1 AND A.CSHR_STAT_CD != 'SL' AND A.DLY_RSN_CD NOT IN ('2', '3') AND A.TER_ID IN ('P', 'P01', 'P02', 'P03') AND A.AC_USE_SE_CD = '0' AND A.GD_FLT_PPS_CD IN ('00', '05') AND A.PAX_CGO_SE_CD = 'Y' AND A.FRY_YN = 'N' AND A.LCRFT_YN = 'N' AND A.GD_SE_DT = TO_CHAR((SELECT BASE_DT FROM PMOWN.DROP_TMP), 'YYYYMMDD') ), /* 3) 항공사 카테고리 */ ALN_INFO AS ( SELECT ALN_CD, MAX(LCC_YN) AS LCC_YN FROM CAOWN.TN_CA_ALN GROUP BY ALN_CD ), /* 4) 게이트 -> 터미널/CRS 그룹 */ GATE_INFO AS ( SELECT GATE_NO, MAX(TER_ID) AS TER_ID, MAX(CRS_GRP_CD) AS CRS_GRP_CD FROM PMOWN.DROP_AA_TN_CA_GATE GROUP BY GATE_NO ), /* 5) 게이트 타입 */ ACST_INFO AS ( SELECT GATE_NO, MIN(ACST_TYPE_CD) AS ACST_TYPE_CD FROM CAOWN.TN_CA_ACST WHERE USE_YN = 'Y' GROUP BY GATE_NO ), /* 6) 셀프체크인 가능 항공사 -> 영어 이름대로 셀프백드랍으로 변경 */ SBD_INFO AS ( SELECT DISTINCT ALN_IATA_CD FROM PMOWN.DROP_AA_SBD_PLCY WHERE USE_YN = 'Y' ), /* 7) 당일 CIC 배정이 존재하는 항공사 */ CIC_ALLOC_ALN AS ( SELECT DISTINCT A.ALN_CD FROM PMOWN.DROP_AA_TN_RS_CIC_DALY_ALLOC A WHERE A.OPR_DT BETWEEN TO_CHAR((SELECT BASE_DT FROM PMOWN.DROP_TMP) - 1, 'YYYYMMDD') AND TO_CHAR((SELECT BASE_DT FROM PMOWN.DROP_TMP), 'YYYYMMDD') ), /* 8) FP 원본 - 당일/익일 04시 이전 */ FP_DAY AS ( SELECT B.FLT_NM, B.SCHD_DT, B.SCHD_HM, MIN(B.ACT_FLT_ID) AS ACT_FLT_ID FROM PMOWN.DROP_AA_TN_FP_ACT_ARR_DEP B WHERE 1 = 1 AND ( B.SCHD_DT = TO_CHAR((SELECT BASE_DT FROM PMOWN.DROP_TMP), 'YYYYMMDD') OR (B.SCHD_DT = TO_CHAR((SELECT BASE_DT FROM PMOWN.DROP_TMP) + 1, 'YYYYMMDD') AND B.SCHD_HM < '0400') ) AND B.FLT_SVC_TY_CD NOT IN ('A', 'F', 'H', 'M', 'V', 'Z', 'P', 'X', 'D') GROUP BY B.FLT_NM, B.SCHD_DT, B.SCHD_HM ), /* 9) CIC_RANGE_CTT - ACT_FLT_ID 기준 */ FP_CIC_BY_ACT AS ( SELECT ACT_FLT_ID, MIN(CIC_RANGE_CTT) AS CIC_RANGE_CTT FROM PMOWN.DROP_AA_TN_FP_ACT_ARR_DEP WHERE CIC_RANGE_CTT IS NOT NULL GROUP BY ACT_FLT_ID ), /* 10) CIC_RANGE_CTT - FLT_NM/SCHD_DT/SCHD_HM 기준 fallback */ FP_CIC_BY_FLT AS ( SELECT FLT_NM, SCHD_DT, SCHD_HM, MIN(CIC_RANGE_CTT) AS CIC_RANGE_CTT FROM PMOWN.DROP_AA_TN_FP_ACT_ARR_DEP WHERE CIC_RANGE_CTT IS NOT NULL GROUP BY FLT_NM, SCHD_DT, SCHD_HM ), /* 11) RS 캐로셀 정보 */ RS_CRS_DAILY AS ( SELECT ARR_ACT_FLT_ID, MIN(CASE WHEN CRS_NO = '0' THEN NULL ELSE CRS_NO END) AS CRS_NO FROM PMOWN.DROP_AA_TN_RS_CRS_DALY_OPR GROUP BY ARR_ACT_FLT_ID ), /* 12) 최근 3개월 기준 closing_flt_nm별 대표 gate/stnd/ter */ PAST_GATE_RANK AS ( SELECT A.CLOSING_FLT_NM, A.TER_ID, A.STND_NO, A.GATE_NO, COUNT(*) AS CNT, ROW_NUMBER() OVER ( PARTITION BY A.CLOSING_FLT_NM ORDER BY COUNT(*) DESC, DBMS_RANDOM.VALUE ) AS RN FROM PMOWN.DROP_AA_TN_AS_GD_DATA A WHERE 1 = 1 AND A.CSHR_STAT_CD != 'SL' AND A.DLY_RSN_CD NOT IN ('2', '3') AND A.TER_ID IN ('P', 'P01', 'P02', 'P03') AND A.AC_USE_SE_CD = '0' AND A.GD_FLT_PPS_CD IN ('00', '05') AND A.PAX_CGO_SE_CD = 'Y' AND A.FRY_YN = 'N' AND A.LCRFT_YN = 'N' AND A.GD_SE_DT BETWEEN TO_CHAR(ADD_MONTHS((SELECT BASE_DT FROM PMOWN.DROP_TMP), - 3), 'YYYYMMDD') AND TO_CHAR((SELECT BASE_DT FROM PMOWN.DROP_TMP) - 1, 'YYYYMMDD') AND A.TER_ID IS NOT NULL AND A.TER_ID != 'P' AND A.STND_NO IS NOT NULL AND A.STND_NO != '0000' AND A.GATE_NO IS NOT NULL GROUP BY A.CLOSING_FLT_NM, A.TER_ID, A.STND_NO, A.GATE_NO ), PAST_GATE AS ( SELECT CLOSING_FLT_NM, TER_ID, STND_NO, GATE_NO FROM PAST_GATE_RANK WHERE RN = 1 ), /* 13) 최근 1개월 도착편 기준 대표 캐로셀 */ ARR_CRS_HIST_RANK AS ( SELECT A.CLOSING_FLT_NM, A.ARR_DEP_SE_CD, A.GATE_NO, A.STND_NO, A.CRS_NO, ROW_NUMBER() OVER ( PARTITION BY A.CLOSING_FLT_NM, A.GATE_NO, A.STND_NO ORDER BY DBMS_RANDOM.VALUE ) AS RN FROM PMOWN.DROP_AA_TN_AS_GD_DATA A WHERE 1 = 1 AND A.GD_SE_DT BETWEEN TO_CHAR(ADD_MONTHS((SELECT BASE_DT FROM PMOWN.DROP_TMP), - 1), 'YYYYMMDD') AND TO_CHAR((SELECT BASE_DT FROM PMOWN.DROP_TMP) - 1, 'YYYYMMDD') AND A.ARR_DEP_SE_CD = 'A' AND A.CSHR_STAT_CD != 'SL' AND A.DLY_RSN_CD NOT IN ('2', '3') AND A.TER_ID IN ('P', 'P01', 'P02', 'P03') AND A.AC_USE_SE_CD = '0' AND A.GD_FLT_PPS_CD IN ('00', '05') AND A.PAX_CGO_SE_CD = 'Y' AND A.FRY_YN = 'N' AND A.LCRFT_YN = 'N' AND A.CRS_NO != '0' AND TRIM(A.GATE_NO) IS NOT NULL AND TRIM(A.CRS_NO) IS NOT NULL ), ARR_CRS_HIST AS ( SELECT CLOSING_FLT_NM, ARR_DEP_SE_CD, GATE_NO, STND_NO, CRS_NO FROM ARR_CRS_HIST_RANK WHERE RN = 1 ), /* 13-2) 최근 3개월 기준 편명별 / 항공사별 평균 승객 수 및 환승객 수 추정 */ PAST_PAX_AVG AS ( SELECT A.CLOSING_FLT_NM, A.ALN_CD, -- [전체 승객 수 평균] ROUND(AVG( CASE WHEN A.INPUT_YN = 'Y' THEN A.TOT_CRG_PAX_CNT + A.TOT_FREE_PAX_CNT + A.TOT_TRPAX_CNT WHEN A.INPUT_YN = 'N' AND A.RSRV_PAX_CNT <> 0 THEN A.RSRV_PAX_CNT ELSE NULL END )) AS AVG_PAX_BY_FLT, ROUND(AVG( CASE WHEN A.INPUT_YN = 'Y' THEN A.TOT_CRG_PAX_CNT + A.TOT_FREE_PAX_CNT + A.TOT_TRPAX_CNT WHEN A.INPUT_YN = 'N' AND A.RSRV_PAX_CNT <> 0 THEN A.RSRV_PAX_CNT ELSE NULL END )) AS AVG_PAX_BY_ALN, -- [환승 승객 수 평균] ROUND(AVG( CASE WHEN A.INPUT_YN = 'Y' AND A.TOT_TRPAX_CNT <> 0 THEN A.TOT_TRPAX_CNT WHEN A.INPUT_YN = 'N' AND A.RSRV_TRPAX_CNT <> 0 THEN A.RSRV_TRPAX_CNT ELSE NULL -- 환승객이 아예 없거나 미입력된 건은 제외하여 정상 환승편의 평균값 보존 END )) AS AVG_TR_PAX_BY_FLT, ROUND(AVG( CASE WHEN A.INPUT_YN = 'Y' AND A.TOT_TRPAX_CNT <> 0 THEN A.TOT_TRPAX_CNT WHEN A.INPUT_YN = 'N' AND A.RSRV_TRPAX_CNT <> 0 THEN A.RSRV_TRPAX_CNT ELSE NULL END )) AS AVG_TR_PAX_BY_ALN FROM PMOWN.DROP_AA_TN_AS_GD_DATA A WHERE 1 = 1 AND A.CSHR_STAT_CD != 'SL' AND A.DLY_RSN_CD NOT IN ('2', '3') AND A.AC_USE_SE_CD = '0' AND A.GD_FLT_PPS_CD IN ('00', '05') AND A.PAX_CGO_SE_CD = 'Y' AND A.FRY_YN = 'N' AND A.LCRFT_YN = 'N' AND A.GD_SE_DT BETWEEN TO_CHAR(ADD_MONTHS((SELECT BASE_DT FROM PMOWN.DROP_TMP), - 3), 'YYYYMMDD') AND TO_CHAR((SELECT BASE_DT FROM PMOWN.DROP_TMP) - 1, 'YYYYMMDD') GROUP BY A.CLOSING_FLT_NM, A.ALN_CD ), /* 14) CA_CRS fallback - TER_ID(+P02->P01), CRS_GRP_CD별 1건 */ CA_CRS_PICK AS ( SELECT CASE WHEN TER_ID = 'P02' THEN 'P01' ELSE TER_ID END AS TER_ID_ADJ, CRS_GRP_CD, CRS_NO, ROW_NUMBER() OVER ( PARTITION BY CASE WHEN TER_ID = 'P02' THEN 'P01' ELSE TER_ID END, CRS_GRP_CD ORDER BY DBMS_RANDOM.VALUE ) AS RN FROM PMOWN.DROP_AA_TN_CA_CRS ), /* ★ [추가] 14-2) 최근 6개월 항공사별 가장 많이 할당된 카운터 범위 (최빈값 구하기) */ PAST_CIC_RANK AS ( SELECT B.ALN_CD, B.CIC_RANGE_CTT, COUNT(*) AS CNT, ROW_NUMBER() OVER ( PARTITION BY B.ALN_CD ORDER BY COUNT(*) DESC, MAX(B.SCHD_DT) DESC -- 많이 쓴 순서, 같으면 최근 날짜 우선 ) AS RN FROM PMOWN.DROP_AA_TN_FP_ACT_ARR_DEP B WHERE B.CIC_RANGE_CTT IS NOT NULL AND B.SCHD_DT BETWEEN TO_CHAR(ADD_MONTHS((SELECT BASE_DT FROM PMOWN.DROP_TMP), - 6), 'YYYYMMDD') AND TO_CHAR((SELECT BASE_DT FROM PMOWN.DROP_TMP) - 1, 'YYYYMMDD') GROUP BY B.ALN_CD, B.CIC_RANGE_CTT ), PAST_CIC AS ( SELECT ALN_CD, CIC_RANGE_CTT FROM PAST_CIC_RANK WHERE RN = 1 ), /* 15) 기준 운항 + 과거 대표값 + FP/RS/CIC 결합 */ BASE_PRE AS ( SELECT B.RESOURCE_ID, B.DOM_INT_SE_CD, B.ARR_DEP_SE_CD, B.ALN_CD, B.FLT_NM, B.CLOSING_FLT_NM, B.FLT_NM_ID, B.SCHD_DT, B.SCHD_HM, B.SCHD_TIME, B.ESTM_TIME, B.ACTL_TIME, B.ARR_DEP_APT_CD, B.CF_TER_ID_X, B.AC_SEAT_CNT, CASE WHEN B.INPUT_YN = 'Y' AND (B.TOT_CRG_PAX_CNT + B.TOT_FREE_PAX_CNT + B.TOT_TRPAX_CNT) BETWEEN 1 AND 1000 THEN B.TOT_CRG_PAX_CNT + B.TOT_FREE_PAX_CNT + B.TOT_TRPAX_CNT WHEN B.INPUT_YN = 'N' AND B.RSRV_PAX_CNT <> 0 THEN B.RSRV_PAX_CNT ELSE COALESCE( PPA.AVG_PAX_BY_FLT, PPA.AVG_PAX_BY_ALN, ROUND(NVL(B.AC_SEAT_CNT, 200) * 0.75) ) END AS PAX_CNT, B.TR_PAX_CNT, B.AC_TYPE, B.IRR_FLT_YN, B.TRDOMFLT_YN, B.FLT_ID, CASE WHEN (B.STND_NO_RAW IS NULL OR B.STND_NO_RAW = '0000') AND PG.STND_NO IS NOT NULL THEN PG.STND_NO WHEN (B.STND_NO_RAW IS NULL OR B.STND_NO_RAW = '0000') AND PG.STND_NO IS NULL THEN '112' ELSE B.STND_NO_RAW END AS STND_NO, CASE WHEN B.GATE_NO_RAW IS NULL AND PG.GATE_NO IS NOT NULL THEN PG.GATE_NO WHEN B.GATE_NO_RAW IS NULL AND PG.GATE_NO IS NULL AND PG.STND_NO IS NOT NULL THEN REPLACE(REPLACE(PG.STND_NO, 'L', ''), 'R', '') WHEN B.GATE_NO_RAW IS NULL AND PG.GATE_NO IS NULL AND PG.STND_NO IS NULL THEN '112' ELSE B.GATE_NO_RAW END AS GATE_NO, COALESCE( B.CRS_NO_RAW, RCD.CRS_NO ) AS CRS_NO_BASE, /* ★ [수정] 당일 CIC 데이터가 없을 경우 6개월 통계치(PC.CIC_RANGE_CTT)를 Fallback으로 연결 */ CASE WHEN B.ARR_DEP_SE_CD = 'D' AND B.TRDOMFLT_YN = 'N' THEN CASE WHEN CA.ALN_CD IS NULL THEN '' ELSE COALESCE(F1.CIC_RANGE_CTT, F2.CIC_RANGE_CTT, PC.CIC_RANGE_CTT, '') END ELSE '' END AS CIC_RANGE_CTT FROM BASE_GD B LEFT JOIN PAST_GATE PG ON B.FLT_NM = PG.CLOSING_FLT_NM LEFT JOIN PAST_PAX_AVG PPA ON B.CLOSING_FLT_NM = PPA.CLOSING_FLT_NM AND B.ALN_CD = PPA.ALN_CD /* [추가] 과거 평균 여객수 Join */ LEFT JOIN FP_DAY FD ON B.FLT_NM = FD.FLT_NM AND B.SCHD_DT = FD.SCHD_DT AND B.SCHD_HM = FD.SCHD_HM LEFT JOIN RS_CRS_DAILY RCD ON FD.ACT_FLT_ID = RCD.ARR_ACT_FLT_ID LEFT JOIN CIC_ALLOC_ALN CA ON B.ALN_CD = CA.ALN_CD LEFT JOIN FP_CIC_BY_ACT F1 ON B.FLT_ID = F1.ACT_FLT_ID LEFT JOIN FP_CIC_BY_FLT F2 ON B.CLOSING_FLT_NM = F2.FLT_NM AND B.SCHD_DT = F2.SCHD_DT AND B.SCHD_HM = F2.SCHD_HM /* ★ [추가] 과거 대표 카운터 Join */ LEFT JOIN PAST_CIC PC ON B.ALN_CD = PC.ALN_CD ), /* 16) 최종 FFF */ FFF AS ( SELECT BP.DOM_INT_SE_CD AS DomStatus, BP.ARR_DEP_SE_CD AS FlightDirection, COALESCE(GI.TER_ID, BP.CF_TER_ID_X) AS DepArrTerminal, BP.ALN_CD AS AirlineCode, CASE WHEN NVL(AI.LCC_YN, 'N') = 'Y' THEN 'LCC' ELSE 'FSC' END AS OperatorCat, BP.FLT_NM AS FlightNumber, BP.FLT_NM_ID AS FlightNumberID, BP.SCHD_TIME AS ScheduleTime, BP.ESTM_TIME AS EstimatedTime, BP.ACTL_TIME AS ActualTime, BP.ARR_DEP_APT_CD AS AirportCode, LPAD(REGEXP_SUBSTR(BP.STND_NO, '^[0-9]+'), 3, '0') || REGEXP_SUBSTR(BP.STND_NO, '[^0-9]+$') AS StandNumber, LPAD(REGEXP_SUBSTR(BP.GATE_NO, '^[0-9]+'), 3, '0') || REGEXP_SUBSTR(BP.GATE_NO, '[^0-9]+$') AS Gate, NVL(AC.ACST_TYPE_CD, 'E') AS ContactRemote, BP.AC_SEAT_CNT AS Seats, BP.PAX_CNT AS PaxCount, CASE WHEN BP.TR_PAX_CNT > BP.PAX_CNT THEN BP.PAX_CNT -- 환승객이 전체 승객보다 많으면 전체 승객수로 제한 ELSE BP.TR_PAX_CNT END AS TransferPax, CASE WHEN BP.ARR_DEP_SE_CD = 'A' THEN COALESCE( BP.CRS_NO_BASE, AH.CRS_NO, CCP.CRS_NO, '' ) ELSE '' END AS Belt, BP.AC_TYPE AS AircraftType, BP.CIC_RANGE_CTT AS CheckinRange, CASE WHEN SB.ALN_IATA_CD IS NOT NULL THEN 'Y' ELSE 'N' END AS SBDAvailable, BP.IRR_FLT_YN AS FlightType, BP.TRDOMFLT_YN AS Triangle, BP.FLT_ID FROM BASE_PRE BP LEFT JOIN GATE_INFO GI ON BP.GATE_NO = GI.GATE_NO LEFT JOIN ALN_INFO AI ON BP.ALN_CD = AI.ALN_CD LEFT JOIN ACST_INFO AC ON BP.GATE_NO = AC.GATE_NO LEFT JOIN SBD_INFO SB ON BP.ALN_CD = SB.ALN_IATA_CD LEFT JOIN ARR_CRS_HIST AH ON BP.FLT_NM = AH.CLOSING_FLT_NM AND BP.GATE_NO = AH.GATE_NO AND BP.STND_NO = AH.STND_NO AND BP.ARR_DEP_SE_CD = AH.ARR_DEP_SE_CD LEFT JOIN CA_CRS_PICK CCP ON CCP.RN = 1 AND CCP.TER_ID_ADJ = CASE WHEN GI.TER_ID = 'P02' THEN 'P01' ELSE GI.TER_ID END AND CCP.CRS_GRP_CD = GI.CRS_GRP_CD ) SELECT FFF.DomStatus, FFF.FlightDirection, FFF.DepArrTerminal, FFF.AirlineCode, FFF.OperatorCat, FFF.FlightNumber, FFF.FlightNumberID, FFF.ScheduleTime, FFF.EstimatedTime, FFF.ActualTime, FFF.AirportCode, FFF.StandNumber, FFF.Gate, FFF.ContactRemote, FFF.Seats, FFF.PaxCount, FFF.TransferPax, FFF.Belt, FFF.AircraftType, FFF.CheckinRange, FFF.SBDAvailable, FFF.FlightType, FFF.Triangle, B.BUS_NEED_YN AS BUS, B.EXIT_ID AS ArrivalGate, CASE WHEN B.FST_BAG_INPT_DTTM IS NULL OR B.FST_BAG_INPT_DTTM = '' THEN NULL ELSE SUBSTR(B.FST_BAG_INPT_DTTM, 1, 4) || '-' || SUBSTR(B.FST_BAG_INPT_DTTM, 5, 2) || '-' || SUBSTR(B.FST_BAG_INPT_DTTM, 7, 2) || 'T' || SUBSTR(B.FST_BAG_INPT_DTTM, 9, 2) || ':' || SUBSTR(B.FST_BAG_INPT_DTTM, 11, 2) || ':00.000' END AS BaggageT1, CASE WHEN B.LST_BAG_INPT_DTTM IS NULL OR B.LST_BAG_INPT_DTTM = '' THEN NULL ELSE SUBSTR(B.LST_BAG_INPT_DTTM, 1, 4) || '-' || SUBSTR(B.LST_BAG_INPT_DTTM, 5, 2) || '-' || SUBSTR(B.LST_BAG_INPT_DTTM, 7, 2) || 'T' || SUBSTR(B.LST_BAG_INPT_DTTM, 9, 2) || ':' || SUBSTR(B.LST_BAG_INPT_DTTM, 11, 2) || ':00.000' END AS BaggageT2 FROM FFF JOIN PMOWN.DROP_AA_TN_RS_FLT_RSC B ON FFF.FLT_ID = B.ACT_FLT_ID ORDER BY FFF.DomStatus, FFF.FlightDirection, FFF.DepArrTerminal, FFF.FlightNumber
SELECT 'FS' || A.SCHDL_ATRB_GROUP_ID AS resourceID , CASE WHEN A.DOM_INTL_SE_CD = 'I' THEN 'Int' WHEN A.DOM_INTL_SE_CD = 'D' AND A.TDFLT_YN = 'Y' THEN 'Int' WHEN A.DOM_INTL_SE_CD = 'D' AND (A.TDFLT_YN != 'Y' OR A.TDFLT_YN IS NULL) THEN 'Dom' ELSE '' END AS domStatus , A.ARR_DEP_SE_CD AS flightDirection , A.TMNL_ID AS depArrTerminal , A.TMNL_ID AS CF_TER_ID_X , A.ALN_CD AS airlineCode , A.ALN_CTGRY AS operatorCat , A.FLTNM AS flightNumber , A.DALY_FLTSH_ID AS dalyFltshId , A.DEP_ARR_YMD AS depArrYmd , A.DEP_ARR_HM AS depArrHm , A.FLTNM || '_' || TO_CHAR(TO_DATE(A.DEP_ARR_YMD, 'YYYY-MM-DD'), 'YYYY-MM-DD') || 'T' || TO_CHAR(TO_DATE(A.DEP_ARR_HM || '00', 'HH24:MI:SS'), 'HH24:MI:SS') || '.000' AS flightNumberID , TO_CHAR(TO_DATE(A.DEP_ARR_YMD, 'YYYY-MM-DD'), 'YYYY-MM-DD') || 'T' || TO_CHAR(TO_DATE(A.DEP_ARR_HM || '00', 'HH24:MI:SS'), 'HH24:MI:SS') || '.000' AS scheduleTime , CASE WHEN A.PREDC_HM IS NOT NULL THEN TO_CHAR(TO_DATE(A.DEP_ARR_YMD, 'YYYY-MM-DD'), 'YYYY-MM-DD') || 'T' || TO_CHAR(TO_DATE(A.PREDC_HM || '00', 'HH24:MI:SS'), 'HH24:MI:SS') || '.000' ELSE '' END AS estimatedTime , CASE WHEN A.ACTL_HM IS NOT NULL THEN TO_CHAR(TO_DATE(A.DEP_ARR_YMD, 'YYYY-MM-DD'), 'YYYY-MM-DD') || 'T' || TO_CHAR(TO_DATE(A.ACTL_HM || '00', 'HH24:MI:SS'), 'HH24:MI:SS') || '.000' ELSE '' END AS actualTime , A.ARR_DEP_ARPT_CD AS airportCode , A.ACST_NO AS standNumber , CASE WHEN TRIM(A.GATE_NO) IS NOT NULL THEN A.GATE_NO WHEN (TRIM(A.GATE_NO) = '' OR TRIM(A.GATE_NO) IS NULL) THEN REPLACE(REPLACE(A.ACST_NO, 'L', ''), 'R', '') WHEN (TRIM(A.GATE_NO) = '' OR TRIM(A.GATE_NO) IS NULL) AND A.TMNL_ID = 'P01' THEN '10' WHEN (TRIM(A.GATE_NO) = '' OR TRIM(A.GATE_NO) IS NULL) AND A.TMNL_ID = 'P02' THEN '112' WHEN (TRIM(A.GATE_NO) = '' OR TRIM(A.GATE_NO) IS NULL) AND A.TMNL_ID = 'P03' THEN '245' ELSE '' END AS gate , A.GATE_TYPE AS contactRemote , A.ARCFT_STGCP AS seats , A.BDPSG_CNT AS paxCount , A.TRNS_BDPSG_CNT AS transferPax , A.CRSL_NO AS belt , A.ARCFT_SUBTYPE_CD AS aircraftType , A.CKNCT_RANGE_CN AS checkInRange , A.SLF_CHKN_PSBLTY_YN AS sbdAvailable , CASE WHEN IRR_FLT_YN IN ('0', 'N') THEN 'Schedule' WHEN IRR_FLT_YN IN ('1', 'Y') THEN 'Charter' ELSE '' END AS flightType , A.TDFLT_YN AS triangle , A.BUS_NEED_YN AS bus , A.WAYO_ID AS arrivalGate , CASE WHEN A.FRST_BAG_INPUT_DT IS NULL OR A.FRST_BAG_INPUT_DT = '' THEN NULL ELSE TO_CHAR(A.FRST_BAG_INPUT_DT, 'YYYY-MM-DD"T"HH24:MI":00.000"') END AS baggageT1 -- 최초수하물투입일시(RS의 운항편자원 정보) , CASE WHEN A.LAST_BAG_INPUT_DT IS NULL OR A.LAST_BAG_INPUT_DT = '' THEN NULL ELSE TO_CHAR(A.LAST_BAG_INPUT_DT, 'YYYY-MM-DD"T"HH24:MI":00.000"') END AS baggageT2 -- 최종수하물투입일시(RS의 운항편자원 정보) FROM PMOWN.TN_PM_SMLT_SCHDL_ATRB A WHERE A.SCHDL_ATRB_GROUP_ID = REPLACE(#{resourceID}, 'FS', '') ORDER BY domStatus, flightDirection, depArrTerminal, flightNumber
) X

/* CastRestTestMapper.retrieveSelfCheckInCountAndBagDrop(CastReqGetResourceDto dto) */ SELECT LISTAGG(BlockID,',') WITHIN GROUP (ORDER BY DepArrTerminal, resourceID, t1, t2) AS BlockID -- BlockID , LISTAGG(resourceID,',') WITHIN GROUP (ORDER BY DepArrTerminal, resourceID, t1, t2) AS resourceID -- 체크인카운터번호 , LISTAGG(DepArrTerminal,',') WITHIN GROUP (ORDER BY DepArrTerminal, resourceID, t1, t2) AS DepArrTerminal -- 터미널아이디 , LISTAGG(AirlineCode,',') WITHIN GROUP (ORDER BY DepArrTerminal, resourceID, t1, t2) AS AirlineCode -- 항공사코드 , LISTAGG(DomStatus,',') WITHIN GROUP (ORDER BY DepArrTerminal, resourceID, t1, t2) AS DomStatus -- 국내국제구분코드 , LISTAGG(t1,',') WITHIN GROUP (ORDER BY DepArrTerminal, resourceID, t1, t2) AS t1 -- 체크인오픈예정시분 , LISTAGG(t2,',') WITHIN GROUP (ORDER BY DepArrTerminal, resourceID, t1, t2) AS t2 -- 체크인클로즈예정시분 , REPLACE(LISTAGG(TravelClass,',') WITHIN GROUP (ORDER BY DepArrTerminal, resourceID, t1, t2),' ','') AS TravelClass -- 체크인등급코드 , REPLACE(LISTAGG(GroupStatus,',') WITHIN GROUP (ORDER BY DepArrTerminal, resourceID, t1, t2),' ','') AS GroupStatus -- 체크인그룹코드 , REPLACE(LISTAGG(CheckinType,',') WITHIN GROUP (ORDER BY DepArrTerminal, resourceID, t1, t2),' ','') AS CheckinType -- 체크인종류코드 , REPLACE(LISTAGG(NonFunctionalStatus,',') WITHIN GROUP (ORDER BY DepArrTerminal, resourceID, t1, t2),' ','') AS NonFunctionalStatus -- 체크인기능코드 , REPLACE(LISTAGG(CheckinAllocType,',') WITHIN GROUP (ORDER BY DepArrTerminal, resourceID, t1, t2),' ','') AS CheckinAllocType -- 체크인유형코드 , REPLACE(LISTAGG(CheckInAllocDescryption,',') WITHIN GROUP (ORDER BY DepArrTerminal, resourceID, t1, t2),' ','') AS CheckInAllocDescryption-- 체크인유형상세정보 , REPLACE(TO_CHAR(SYSDATE,'yyyy-mm-dd hh24:mi:ss'),' ','T') AS lastModified FROM (
SELECT CASE WHEN SUBSTR(CHKN_INTR_ID, 4, 1) = '1' THEN 'P01Self' ELSE 'P03Self' END AS BlockID , CASE WHEN SUBSTR(CHKN_INTR_ID, 4, 1) = '1' THEN 'P01' ELSE 'P03' END AS DepArrTerminal , CHKN_INTR_ID AS resourceID , '"' || LISTAGG(ALN_CD, ',') WITHIN GROUP (ORDER BY ALN_CD) || '"' AS AirlineCode , 'Int' AS DomStatus , TO_CHAR((SELECT BASE_DT FROM PMOWN.DROP_TMP)-1, 'YYYY-MM-DD') || 'T12:00:00.000' AS t1 , TO_CHAR((SELECT BASE_DT FROM PMOWN.DROP_TMP), 'YYYY-MM-DD') || 'T23:59:59.000' AS t2 , '' AS TravelClass -- 체크인등급코드 , '' AS GroupStatus -- 체크인그룹코드 , '' AS CheckinType -- 체크인종류코드 , '' AS NonFunctionalStatus -- 체크인기능코드 , 'C' AS CheckinAllocType -- 체크인유형코드 , '"' || LISTAGG(ALN_CD, ',') WITHIN GROUP (ORDER BY ALN_CD) || '"' AS CheckInAllocDescryption -- 체크인유형상세정보 FROM PMOWN.DROP_AA_SELF_CHKN_ALN GROUP BY SUBSTR(CHKN_INTR_ID, 4, 1), CHKN_INTR_ID UNION ALL SELECT BlockID , DepArrTerminal , resourceID , '"' ||(SELECT LISTAGG(ALN, ',') WITHIN GROUP (ORDER BY ALN) FROM (SELECT DISTINCT REGEXP_SUBSTR(SBD.AirlineCode, '[^,]+', 1,LEVEL) AS ALN FROM DUAL CONNECT BY REGEXP_SUBSTR(SBD.AirlineCode, '[^,]+', 1 , LEVEL) IS NOT NULL)) || '"' AS AirlineCode -- 항공사코드 , DomStatus , t1 , t2 , '' AS TravelClass -- 체크인등급코드 , '' AS GroupStatus -- 체크인그룹코드 , '' AS CheckinType -- 체크인종류코드 , '' AS NonFunctionalStatus -- 체크인기능코드 , 'C' AS CheckinAllocType -- 체크인유형코드 , '"' ||(SELECT LISTAGG(ALN, ',') WITHIN GROUP (ORDER BY ALN) FROM (SELECT DISTINCT REGEXP_SUBSTR(SBD.AirlineCode, '[^,]+', 1,LEVEL) AS ALN FROM DUAL CONNECT BY REGEXP_SUBSTR(SBD.AirlineCode, '[^,]+', 1 , LEVEL) IS NOT NULL)) || '"' AS CheckInAllocDescryption -- 체크인유형상세정보 FROM ( SELECT CASE WHEN CIC.TMNL_ID = 'P03' THEN 'P03SBD' ELSE 'P01SBD' END AS BlockID -- BlockID , CIC.TMNL_ID AS DepArrTerminal -- 터미널아이디 , CIC.CKNCT_ID AS resourceID -- 체크인카운터번호 , LISTAGG(PLCY.ALN_IATA_CD, ',') WITHIN GROUP (ORDER BY PLCY.ALN_IATA_CD) AS AirlineCode -- 항공사코드 , CASE WHEN CIC.DOM_INTL_SE_CD = 'I' THEN 'Int' ELSE 'Dom' END AS DomStatus -- 국내국제구분코드 , TO_CHAR(TO_DATE(MIN(GD.OPEN_TM), 'YYYYMMDDHH24MISS'), 'YYYY-MM-DD"T"HH24:MI:SS".000"') AS t1 , TO_CHAR(TO_DATE(MAX(GD.CLOSE_TM), 'YYYYMMDDHH24MISS'), 'YYYY-MM-DD"T"HH24:MI:SS".000"') AS t2 FROM CAOWN.TN_CA_CKNCT CIC LEFT JOIN PMOWN.DROP_AA_SBD_PLCY PLCY ON CIC.TMNL_ID = PLCY.TMNL_ID AND SUBSTR(CIC.CKNCT_ID, 1, 1) = PLCY.ISLAND LEFT JOIN ( SELECT A.GD_SE_DT , A.TER_ID , A.ALN_CD , MIN(TO_CHAR(TO_DATE(A.GD_SE_DT || A.SCHD_HM, 'YYYYMMDDHH24MISS') - 5/24, 'YYYYMMDDHH24MISS')) AS OPEN_TM , MAX(TO_CHAR(TO_DATE(A.GD_SE_DT || A.SCHD_HM, 'YYYYMMDDHH24MISS') - 1/24, 'YYYYMMDDHH24MISS')) AS CLOSE_TM FROM PMOWN.DROP_AA_TN_AS_GD_DATA A WHERE 1=1 AND A.CSHR_STAT_CD != 'SL' AND A.DLY_RSN_CD NOT IN ('2', '3') AND A.TER_ID IN ('P', 'P01', 'P02', 'P03') AND A.AC_USE_SE_CD = '0' AND A.GD_FLT_PPS_CD IN ('00', '05') AND A.PAX_CGO_SE_CD = 'Y' AND A.ARR_DEP_SE_CD = 'D' AND A.FRY_YN = 'N' AND A.LCRFT_YN = 'N' AND A.GD_SE_DT BETWEEN TO_CHAR((SELECT BASE_DT FROM PMOWN.DROP_TMP) -1, 'YYYYMMDD') AND TO_CHAR((SELECT BASE_DT FROM PMOWN.DROP_TMP), 'YYYYMMDD') GROUP BY A.GD_SE_DT, A.TER_ID, A.ALN_CD ) GD ON PLCY.ALN_IATA_CD = GD.ALN_CD AND CIC.TMNL_ID = GD.TER_ID WHERE 1=1 AND CIC.USE_YN = 'Y' AND CIC.CKNCT_USE_CRG_APLCN_TYPE_CD = 'H' AND GD.OPEN_TM IS NOT null GROUP BY CIC.TMNL_ID, CIC.CKNCT_ID, CIC.DOM_INTL_SE_CD ) SBD ORDER BY BlockID, DepArrTerminal, resourceID
SELECT CASE WHEN TMNL_ID = 'P01' THEN 'P01SBD' WHEN TMNL_ID = 'P03' THEN 'P03SBD' ELSE 'P03Self' END AS BlockID , Y.TMNL_ID AS DepArrTerminal , Y.CKNCT_ID AS resourceID , '"' || Y.CHKN_TYPE_DTL_INFO || '"' AS AirlineCode , CASE WHEN Y.DOM_INTL_SE_CD = 'I' THEN 'Int' ELSE 'Dom' END AS DomStatus -- 국내국제구분코드 , TO_CHAR(TO_DATE(Y.STA_DT, 'YYYYMMDDHH24MI'), 'YYYY-MM-DD"T"HH24:MI":00"') AS t1 , TO_CHAR(TO_DATE( CASE WHEN Y.RON_YN = 'N' THEN Y.OPR_DT ELSE TO_CHAR(TO_DATE(Y.OPR_DT, 'YYYYMMDD') + 1, 'YYYYMMDD') END || SUBSTR(Y.END_DT,9,2), 'YYYYMMDDHH24MI' ), 'YYYY-MM-DD"T"HH24:MI":00"') AS t2 , Y.TRVL_CLSS AS TravelClass , Y.GRP_STAT AS GroupStatus , Y.CIC_TYPE AS CheckInType , Y.NONFUNC_STAT AS NonFunctionalStatus , Y.CHKN_TYPE_CD AS CheckInAllocType , '"' || Y.CHKN_TYPE_DTL_INFO || '"' AS CheckInAllocDescryption FROM (SELECT A.TMNL_ID , A.CKNCT_ID , A.ALN_CD , A.DOM_INTL_SE_CD , A.CRTR_YMD AS OPR_DT , A.OPER_BGNG_DT AS STA_DT , A.OPER_END_DT AS END_DT
, CASE WHEN TO_NUMBER(A.OPER_BGNG_DT) <= TO_NUMBER(A.OPER_END_DT) THEN 'N' ELSE 'Y' END AS RON_YN
, NVL(A.CHKN_GRD_CD,' ') AS TRVL_CLSS , NVL(A.CHKN_GROUP_CD,' ') AS GRP_STAT , NVL(A.CHKN_KND_CD,' ') AS CIC_TYPE , NVL(A.CHKN_FWK_CD,' ') AS NONFUNC_STAT , NVL(A.CHKN_TYPE_CD,' ') AS CHKN_TYPE_CD , NVL(A.CHKN_TYPE_DTL_INFO,' ') AS CHKN_TYPE_DTL_INFO FROM PMOWN.TN_PM_SMLT_SBD_ATRB A WHERE SCHDL_ATRB_GROUP_ID = REPLACE(#{resourceID}, 'SBD', '')) Y ORDER BY DepArrTerminal, t1, t2
) K ORDER BY t1, t2

    /* CastRestTestMapper.retrieveNewCastModelId(CastModelDto dto) */
SELECT NVL(MAX(TO_NUMBER(SMLT_MDL_SN)),0)+1 AS smltMdlSn
  FROM PMOWN.TN_PM_SMLT_MDL

mapper.insert:
/* CastRestTestMapper.insertCASTModel(SmltMdlDto dto) */
INSERT INTO PMOWN.TN_PM_SMLT_MDL
(
    SMLT_MDL_SN
    , SMLT_MDL_EXPLN
    , SMLT_MDL_FILE_PATH_NM
    , DEL_YN
    , SMLT_MDL_TYPE_CD
    , FRST_RGTR_ID
    , FRST_RGTR_IP_ADDR
    , FRST_REG_DT
) VALUES (
    #{smltMdlSn}
    , #{smltMdlExpln}
    , #{smltMdlFilePathNm}
    , 'N'
    , #{smltMdlTypeCd}
    , 'system'
    , #{loginIpAddr}
    , CURRENT_TIMESTAMP
)

mapper.update:
 /* CastRestTestMapper.updateCASTModel(CastModelDto dto) */
UPDATE PMOWN.TN_PM_SMLT_MDL SET
       LAST_MDFR_ID = 'SYSTEM'
    , LAST_MDFR_IP_ADDR = #{loginIpAddr}
    , LAST_MDFCN_DT = CURRENT_TIMESTAMP
 WHERE SMLT_MDL_EXPLN = #{resourceID}

 /* CastRestTestMapper.deleteCASTModel(CastResReqDto dto) */
UPDATE PMOWN.TN_PM_SMLT_MDL SET
      DEL_YN = 'Y'
    , LAST_MDFR_ID = 'SYSTEM'
    , LAST_MDFR_IP_ADDR = #{loginIpAddr}
    , LAST_MDFCN_DT = CURRENT_TIMESTAMP
WHERE SMLT_MDL_EXPLN = #{resourceID}

mapper.select:
    /* CastRestTestMapper.retrieveModelInfo(CastModelDto dto) */
SELECT SMLT_MDL_SN AS smltMdlSn
    , SMLT_MDL_TYPE_CD AS smltMdlTypeCd
    , SMLT_EXCN_SE_CD smltExcnSeCd
  FROM PMOWN.TN_PM_SMLT_MDL
  WHERE SMLT_MDL_EXPLN = #{modelResourceID}

/* CastRestTestMapper.retrieveSimId(CastResReqDto dto) */
SELECT PMOWN.SQ1_TN_PM_SMLT_RSLT.NEXTVAL
  FROM DUAL

    /* CastRestTestMapper.checkFcltCd(SimRsltDto dto) */
SELECT PSG_FCLT_CD AS psgFcltCd
FROM PMOWN.TN_PM_SMLT_PSG_FCLT
WHERE USE_YN = 'Y'
AND SMLT_FCLT_NM = #{paxFcltCd}

mapper.insert:
    /* CastRestTestMapper.insertSimSet(CastResReqDto dto) */
INSERT INTO PMOWN.TN_PM_SMLT_STNG
         (  SMLT_ID
          , SMLT_MDL_SN
          , SMLT_NM
          , SMLT_TYPE
          , CRTR_DT
          , EXCN_YMD
          , TMNL_ID              
          , SLF_ID
          , PRNT_ID
          , FLT_SCHDL_RSRC_ID
          , BAG_ALCTN_RSRC_ID
          , CKNCT_ALCTN_RSRC_ID
          , PRPT_SET_RSRC_ID
          , MDL_RSRC_ID
          , EXCN_ID
          , CKNCT_SRVC_HR_RSRC_ID
          , CHKN_TYPE_RSRC_ID
          , FCLTY_OPNG_TBL_DG_RSRC_ID
          , FCLTY_OPNG_TBL_EMI_RSRC_ID
          , FCLTY_OPNG_TBL_IMMI_RSRC_ID
          , FCLTY_OPNG_TBL_SCRTY_CNTRL_RSRC_ID
          , FCLTY_OPNG_TBL_TR_SCRTY_CNTRL_RSRC_ID
          , SBD_CNTRL_ALCTN_ID
          , PLAN_BGNG_DT
          , PLAN_END_DT
          , SMLT_BGNG_DT
          , SMLT_END_DT              
          , BDPSG_ANCE_YN
          , FRST_RGTR_ID
          , FRST_RGTR_IP_ADDR
          , FRST_REG_DT)
VALUES (    #{simId}
          , #{smltMdlSn}
          , #{resourceID}
          , #{smltType}
          , CURRENT_TIMESTAMP
          , substr(replace(replace(#{startTime},'T',' '),'-',''),1,8)
          , 'P01'
          , #{selfID}
          , #{parentID}              
          , #{flightScheduleResourceID}
          , #{bagAllocationResourceID}
          , #{checkInAllocationResourceID}
          , #{propertySetResourceID}
          , #{modelResourceID}
          , #{runID}
          , #{checkinCounterServiceTimeResourceID}
          , #{checkinTypeResourceID}
          , #{facilityOpeningTableDepartureGateResourceID}
          , #{facilityOpeningTableEmigrationResourceID}
          , #{facilityOpeningTableImmigrationResourceID}
          , #{facilityOpeningTableSecurityControlResourceID}
          , #{facilityOpeningTableTransferSecurityControlResourceID}
          , #{sbdCounterAllocationResourceID}
          , substr(replace(#{startTime},'T',' '),1,19)              
          , substr(replace(#{stopTime},'T',' '),1,19)
          , substr(replace(#{simulationStartTime},'T',' '),1,19)              
          , substr(replace(#{simulationStopTime},'T',' '),1,19)              
          , #{paxAnnceYn}
          , 'CAST'
          , #{loginIpAddr}
          , CURRENT_TIMESTAMP)

