FROM PMOWN.TN_PM_SMLT_STNG
WHERE SMLT_ID = #{smltId}
   AND SMLT_MDL_SN = (SELECT SMLT_MDL_SN FROM PMOWN.TN_PM_SMLT_MDL WHERE SMLT_MDL_EXPLN = #{smltMdlExpln})

