          WTNG_PSG_CNT = INT(WTNG_PSG_CNT)+TO_NUMBER(#{wtngPsgCnt})
        , TRNST_PSG_CNT = INT(TRNST_PSG_CNT)+TO_NUMBER(#{trnstPsgCnt})
WHERE SMLT_ID = #{smltId}
    AND SMLT_MDL_SN = #{smltMdlSn}
    AND SMLT_RSLT_SN = #{smltRsltSn}

