        /* CastRestMapper.updateWhatIfDefinitionTable(CastWhatIfCntrlDto dto) */
	    UPDATE PMOWN.TN_PM_SMLT_WHAT_IF_DEF_TBL 
	    SET    WHAT_IF_STTS = #{status}
	         , EXCT_DT = CASE
                           WHEN #{status} = 'Executing' THEN CURRENT_TIMESTAMP
                            ELSE EXCT_DT
                         END
	         , LAST_MDFR_ID = 'SYSTEM'
             , LAST_MDFR_IP_ADDR = #{loginIpAddr}
             , LAST_MDFCN_DT = CURRENT_TIMESTAMP
	    WHERE WHAT_IF_EXCN_ID = #{whatIfRunId}
	    AND WHAT_IF_STTS != #{status}

